{
  "name": "http-status-server",
  "version": "1.0.0",
  "description": "Node.js HTTP server backed by a lookup table of HTTP status codes and their reason phrases.",
  "private": true,
  "main": "src/server.js",
  "scripts": {
    "start": "node src/index.js",
    "test": "node --test"
  },
  "engines": {
    "node": ">=18"
  },
  "license": "MIT"
}

'use strict';

const http = require('node:http');
const { STATUS_CODES, getReasonPhrase, isStatusCode } = require('./status-codes');

function sendJson(res, statusCode, payload) {
  const body = JSON.stringify(payload, null, 2);
  res.writeHead(statusCode, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(body)
  });
  res.end(body);
}

function handleRequest(req, res) {
  const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
  const segments = url.pathname.split('/').filter(Boolean);

  if (req.method !== 'GET') {
    sendJson(res, 405, { error: getReasonPhrase(405) });
    return;
  }

  if (segments.length === 0) {
    sendJson(res, 200, {
      name: 'http-status-server',
      endpoints: {
        'GET /status': 'List every known status code and reason phrase.',
        'GET /status/:code': 'Respond with the given status code and its reason phrase.'
      }
    });
    return;
  }

  if (segments[0] !== 'status') {
    sendJson(res, 404, { error: getReasonPhrase(404) });
    return;
  }

  if (segments.length === 1) {
    sendJson(res, 200, { statusCodes: STATUS_CODES });
    return;
  }

  const raw = segments[1];

  if (!/^\d{3}$/.test(raw) || !isStatusCode(raw)) {
    sendJson(res, 400, { error: getReasonPhrase(400), code: raw });
    return;
  }

  const code = Number(raw);
  sendJson(res, code, { code, reason: getReasonPhrase(code) });
}

function createServer() {
  return http.createServer(handleRequest);
}

module.exports = { createServer, handleRequest };

'use strict';

const { createServer } = require('./server');

const port = Number(process.env.PORT) || 3000;
const host = process.env.HOST || '127.0.0.1';
const server = createServer();

server.listen(port, host, () => {
  const address = server.address();
  console.log(`http-status-server listening on http://${address.address}:${address.port}`);
});

module.exports = server;

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { STATUS_CODES, getReasonPhrase, isStatusCode } = require('../src/status-codes');

test('contains the standard reason phrases', () => {
  assert.equal(getReasonPhrase(200), 'OK');
  assert.equal(getReasonPhrase(404), 'Not Found');
  assert.equal(getReasonPhrase(418), "I'm a Teapot");
  assert.equal(getReasonPhrase(500), 'Internal Server Error');
});

test('accepts numeric strings', () => {
  assert.equal(getReasonPhrase('301'), 'Moved Permanently');
  assert.equal(isStatusCode('204'), true);
});

test('falls back for unknown codes', () => {
  assert.equal(getReasonPhrase(999), 'Unknown Status Code');
  assert.equal(isStatusCode(999), false);
  assert.equal(isStatusCode('abc'), false);
});

test('lookup table is immutable', () => {
  assert.throws(() => {
    STATUS_CODES[200] = 'Broken';
  }, TypeError);
});

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { createServer } = require('../src/server');

function withServer(run) {
  return async () => {
    const server = createServer();
    await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
    const { port } = server.address();
    try {
      await run(`http://127.0.0.1:${port}`);
    } finally {
      await new Promise((resolve) => server.close(resolve));
    }
  };
}

test('GET /status returns the full lookup table', withServer(async (base) => {
  const res = await fetch(`${base}/status`);
  assert.equal(res.status, 200);
  const body = await res.json();
  assert.equal(body.statusCodes[404], 'Not Found');
}));

test('GET /status/:code responds with that status and phrase', withServer(async (base) => {
  const res = await fetch(`${base}/status/418`);
  assert.equal(res.status, 418);
  assert.equal(res.statusText, "I'm a Teapot");
  assert.deepEqual(await res.json(), { code: 418, reason: "I'm a Teapot" });
}));

test('unknown code returns 400', withServer(async (base) => {
  const res = await fetch(`${base}/status/999`);
  assert.equal(res.status, 400);
}));

test('unknown path returns 404', withServer(async (base) => {
  const res = await fetch(`${base}/nope`);
  assert.equal(res.status, 404);
}));

